    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    def mode(seq):
        return Counter(seq).most_common(1)[0][0]

    rows = []
    for r, row in enumerate(grid):
        counts = Counter(row)
        m = counts.most_common(1)[0][0]
        if m != background and counts[m] / w >= 0.65:
            rows.append(r)

    cols = []
