from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]

    row_modes = [Counter(row).most_common(1)[0][0] for row in grid]
    col_modes = [
        Counter(grid[r][c] for r in range(h)).most_common(1)[0][0]
        for c in range(w)
    ]

    def stripe_color(modes):
        counts = Counter(x for x in modes if x != bg)
        return counts.most_common(1)[0][0] if counts else None

    rs, cs = stripe_color(row_modes), stripe_color(col_modes)
    rows = [r for r, x in enumerate(row_modes) if x == rs]
    cols = [c for c, x in enumerate(col_modes) if x == cs]

    if len(rows) < 2 or len(cols) < 2:
        return grid

    # Keep only the active portion of the repeated lattice.
    active_cols = [
        j for j, c in enumerate(cols)
        if any(grid[r][c] != cs for r in rows)
    ]
    active_rows = [
        i for i, r in enumerate(rows)
        if any(grid[r][c] != rs for c in cols)
    ]
    if active_cols:
        cols = cols[min(active_cols):max(active_cols) + 1]
    if active_rows:
        rows = rows[min(active_rows):max(active_rows) + 1]

    out = []
    for i in range(len(rows) - 1):
        line = []
        for j in range(len(cols) - 1):
            corners = (
                grid[rows[i]][cols[j]],
                grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]],
                grid[rows[i + 1]][cols[j + 1]],
            )
            line.append(corners[0] if len(set(corners)) == 1 else bg)
        out.append(line)
    return out
